package ultra.downloads;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import java.lang.reflect.*;
public class NativeMenuTest{
 @Test public void nativeSongCommandRetainsIdentity()throws Exception{Object command=NativeModels.command("abcdefghijk",null);assertEquals("bjue",command.getClass().getName());Class<?> cls=Class.forName("com.google.protos.youtube.api.innertube.OfflineVideoEndpointOuterClass$OfflineVideoEndpoint");Object ext=cls.getField("offlineVideoEndpoint").get(null);Object raw=command.getClass().getSuperclass().getDeclaredField("j").get(command);Object descriptor=ext.getClass().getField("d").get(ext);Object endpoint=raw.getClass().getMethod("l",Class.forName("bhbh")).invoke(raw,descriptor);assertEquals("abcdefghijk",endpoint.getClass().getField("d").get(endpoint));assertEquals(1,((Number)endpoint.getClass().getField("c").get(endpoint)).intValue());}
 @Test public void nativePlaylistCommandRetainsIdentity()throws Exception{Object command=NativeModels.command(null,"PLexamplePlaylist");assertNotNull(command);}
 public static class Selected {public String k(Object model){return "abcdefghijk";}public String m(Object model){return "PLdifferentPlaylist";}}
 @Test public void upsellBecomesCleanNativeSongDownload()throws Exception{Object original=NativeModels.fresh("bpnf");Object output=NativeModels.rewriteUpsell(original,new Object(),new Selected());assertNotSame(original,output);Object service=output.getClass().getField("d").get(output);Object text=service.getClass().getField("c").get(service);assertEquals("Download",text.getClass().getField("d").get(text));Object command=service.getClass().getField("e").get(service);assertNotNull(command);}
 @Test public void realHostModelHelperUsesSelectedSong()throws Exception{Object model=NativeModels.fresh("bsca");NativeModels.set(model,"b",1);NativeModels.set(model,"c","abcdefghijk");Class<?> provider=Class.forName("ccoj");Object helper=Class.forName("kht").getConstructor(provider,provider).newInstance(null,null);assertEquals("abcdefghijk",helper.getClass().getMethod("k",Object.class).invoke(helper,model));Object original=NativeModels.fresh("bpnf");Object rewritten=NativeModels.rewriteUpsell(original,model,helper);assertNotSame(original,rewritten);}
}
